extracted_python_code:
result = Customers.WHERE(
    (join_date >= "2023-01-01") & (status == "Active")
).PARTITION(name="country_group", by=country).CALCULATE(
    country=country,
    TAC=COUNT(Customers)
)

frequently_bought_stocks = Tickers.CALCULATE(
    ticker_symbol=symbol,
    num_buy_transactions=COUNT(
        transactions_of.WHERE(
            (DATEDIFF("days", date_time, DATETIME('now')) <= 10) & 
            (transaction_type == "buy")
        )
    )
).TOP_K(2, by=num_buy_transactions.DESC())

acp_by_type = DailyPrices.WHERE(
    DATEDIFF("days", date, DATETIME('now')) <= 6
).CALCULATE(
    ticker_type=ticker.ticker_type
).PARTITION(
    name="type_groups", by=(ticker_type)
).CALCULATE(
    ticker_type=ticker_type,
    average_closing_price=AVG(DailyPrices.close)
)

result = Customers.WHERE(
    (YEAR(join_date) == 2022) & (HAS(transactions_made) == 1)
).PARTITION(name="country_group", by=(country)).CALCULATE(
    country=country,
    AR = 100.0 * COUNT(Customers.WHERE(status == 'active')) / COUNT(Customers)
)

customer_count = Broker.CALCULATE(
    num_customers=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

result = Tickers.CALCULATE(
    ticker_symbol=symbol,
    sell_transactions_last_month=transactions_of.WHERE(
        (transaction_type == 'Sell') & (date_time >= DATETIME('now', '-1 month'))
    )
).WHERE(
    HAS(sell_transactions_last_month) == 1
).CALCULATE(
    ticker_symbol=ticker_symbol,
    total_amount=SUM(sell_transactions_last_month.amount),
    total_costs=SUM(sell_transactions_last_month.tax) + SUM(sell_transactions_last_month.commission)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    SPM=IFF(total_amount != 0, (total_amount - total_costs) / total_amount * 100.0, 0.0)
)

top_stocks_by_price_change = DailyPrices.WHERE(
    (date >= "2023-04-01") & (date <= "2023-04-04")
).CALCULATE(
    ticker_symbol=ticker.symbol
).PARTITION(
    name="ticker_prices", by=(ticker_symbol)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    price_change=MAX(DailyPrices.high) - MIN(DailyPrices.low)
).TOP_K(3, by=price_change.DESC())

result = Transactions.WHERE(
    (date_time >= "2023-01-01") & (date_time < "2023-04-01")
).PARTITION(
    name="transaction_groups", by=transaction_type
).CALCULATE(
    transaction_type=transaction_type,
    num_distinct_customers=NDISTINCT(Transactions.customer_id),
    avg_shares=AVG(Transactions.shares)
).TOP_K(3, by=num_distinct_customers.DESC())

distinct_customer_ids = Transactions.WHERE(
    transaction_type == 'buy'
).PARTITION(
    name="customers", by=(customer_id)
).CALCULATE(
    customer_id=customer_id
)

distinct_ticker_ids = DailyPrices.WHERE(date >= "2023-04-01").PARTITION(
    name="ticker_groups", by=(ticker_id)
).CALCULATE(
    ticker_id=ticker_id
)

top_countries_by_amount = Transactions.WHERE(
    DATEDIFF("days", date_time, DATETIME('now')) <= 30
).CALCULATE(
    country=customer.country
).PARTITION(name="country_groups", by=country).CALCULATE(
    country_name=country,
    number_of_transactions=COUNT(Transactions),
    total_transaction_amount=SUM(Transactions.amount)
).TOP_K(5, by=total_transaction_amount.DESC())

lowest_price_vti = Broker.CALCULATE(
    lowest_daily_close_price=MIN(
        DailyPrices.WHERE(
            (ticker.symbol == 'VTI') & (DATEDIFF("days", date, 'now') <= 7)
        ).close
    )
)

result = Broker.CALCULATE(
    num_transactions=COUNT(Transactions.WHERE(DATEDIFF("days", customer.join_date, 'now') <= 70))
)

monthly_average_prices = Transactions.WHERE(
    (status == 'success') &
    (YEAR(date_time) == 2023) &
    (MONTH(date_time) <= 3)
).CALCULATE(
    month=MONTH(date_time)
).PARTITION(
    name="monthly_transactions",
    by=(month)
).CALCULATE(
    month=month,
    average_price=AVG(Transactions.price)
).ORDER_BY(month.ASC())

result = Dealership.CALCULATE(
    asp=AVG(Sales.WHERE((YEAR(sale_date) == 2023) & (MONTH(sale_date) <= 3)).sale_price)
)

result = Dealership.CALCULATE(
    avg_days_to_payment=ROUND(
        AVG(
            PaymentsReceived.CALCULATE(
                days_diff=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_diff
        ),
        2
    )
)

highest_priced_car_sold_on_inventory_out_day = Sales.WHERE(
    HAS(
        car.inventory_snapshots.WHERE(
            (is_in_inventory == False) & (snapshot_date == sale_date)
        )
    ) == 1
).TOP_K(
    1, by=sale_price.DESC()
).CALCULATE(
    make=car.make,
    model=car.model,
    sale_price=sale_price
)

total_sales_count = Dealership.CALCULATE(
    TSC=COUNT(Sales.WHERE(DATEDIFF("days", sale_date, 'now') < 7))
)

result = Customers.WHERE(HAS(car_purchases) == 1).CALCULATE(
    customer_id=_id
)

salespersons_with_cash_payments = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(payment_method == 'Cash')) == 1
).CALCULATE(
    salesperson_id=_id
)

# Calculate the average DDD for each drug, considering only treatments with a valid duration.
# DDD is defined as the total drug amount divided by the treatment duration in days.
avg_ddd_per_drug = Drugs.CALCULATE(
    drug_name=drug_name,
    avg_ddd=AVG(
        treatments_used_in.WHERE(
            (HAS(end_dt) == 1) & (DATEDIFF("days", start_dt, end_dt) > 0)
        ).CALCULATE(
            ddd_value=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd_value
    )
)

result = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            ENDSWITH(email, "@gmail.com") | ENDSWITH(email, "@yahoo.com")
        )
    )
)

psoriasis_biologic_patients_count = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (diagnosis.diag_name == 'Psoriasis vulgaris') & (drug.drug_type == 'biologic')
                )
            ) == 1
        )
    )
)

alice_treatments_count = DermTreatment.CALCULATE(
    start_of_current_month=DATETIME('now', 'start of month'),
    start_of_range=DATETIME('now', 'start of month', '-6 months')
).Patients.WHERE(
    first_name == "Alice"
).CALCULATE(
    num_treatments=COUNT(treatments_received.WHERE(
        (start_dt >= start_of_range) & (start_dt < start_of_current_month)
    ))
)

avg_patient_weight = Drugs.WHERE(drug_name == 'Drugalin').CALCULATE(
    avg_weight=AVG(treatments_used_in.patient.weight_kg)
)

male_patient_caw = DermTreatment.CALCULATE(
    caw=AVG(Patients.WHERE(gender == 'Male').weight_kg)
)

npi_by_year = Patients.CALCULATE(
    first_treatment_year=YEAR(MIN(treatments_received.start_dt))
).PARTITION(
    name="yearly_new_patients", by=(first_treatment_year)
).CALCULATE(
    year=first_treatment_year,
    num_new_patients=COUNT(Patients)
).CALCULATE(
    year=year,
    num_new_patients=num_new_patients,
    NPI=num_new_patients - PREV(num_new_patients, by=year.ASC())
).ORDER_BY(year.ASC())

pic_count = DermTreatment.CALCULATE(
    pic_female_patients=COUNT(Patients.WHERE((gender == 'female') & (ins_type == 'private')))
)

drug_with_most_adverse_events = Drugs.CALCULATE(
    drug_id=drug_id,
    drug_name=drug_name,
    num_adverse_events=COUNT(
        treatments_used_in.adverse_events.WHERE(
            (YEAR(reported_dt) == YEAR(treatments_used_in.start_dt)) & 
            (MONTH(reported_dt) == MONTH(treatments_used_in.start_dt))
        )
    )
).TOP_K(1, by=num_adverse_events.DESC())

biologic_doctor_states = Doctors.WHERE(
    HAS(prescribed_treatments.WHERE(drug.drug_type == 'biologic')) == 1
).PARTITION(
    name="states", by=loc_state
).CALCULATE(
    state=loc_state
)

top_diagnoses_by_itch_score = Diagnoses.WHERE(
    HAS(treatments_for.outcome_records) == 1
).CALCULATE(
    diagnosis_name=diag_name,
    num_patients=NDISTINCT(treatments_for.patient.patient_id),
    max_itch_score=MAX(treatments_for.outcome_records.day100_itch_vas)
).TOP_K(
    3,
    by=max_itch_score.DESC()
)

first_treatment_by_doctor = Doctors.WHERE(
    year_reg == YEAR(DATETIME('now')) - 2
).CALCULATE(
    first_treatment=prescribed_treatments.WHERE(
        RANKING(by=start_dt.ASC(), per="Doctors") == 1
    ).SINGULAR()
).CALCULATE(
    last_name=last_name,
    year_of_registration=year_reg,
    first_treatment_id=first_treatment.treatment_id,
    first_treatment_date=first_treatment.start_dt
)

result = DermTreatment.CALCULATE(
    avg_patient_age=ROUND(
        AVG(
            Patients.WHERE((gender == 'male') & (ins_type == 'private')).CALCULATE(
                age=DATEDIFF("years", date_of_birth, DATETIME('now'))
            ).age
        ),
        0
    )
)

marketing_preferences = Users.CALCULATE(
    user_id=uid,
    marketing_opt_in=setting_snapshots.WHERE(
        RANKING(by=snapshot_date.DESC(), per="Users") == 1
    ).SINGULAR().marketing_opt_in
)

mrr_calculation = Merchants.CALCULATE(
    revenue_amount=SUM(
        transactions_received.WHERE(
            (status == 'success') & (receiver_type == 1)
        ).amount
    )
).CALCULATE(
    merchant_name=name,
    category=category,
    revenue_amount=revenue_amount,
    revenue_rank=RANKING(by=revenue_amount.DESC())
)

# Define a contextless expression to filter sessions within the specified date range.
sessions_in_range = sessions.WHERE(
    (session_start_ts >= "2023-06-01") & (session_start_ts < "2023-06-08")
)

# Calculate the total session duration for each user and sort the results.
result = Users.WHERE(
    HAS(sessions_in_range) == 1
).CALCULATE(
    user_id=uid,
    total_duration=SUM(
        sessions_in_range.CALCULATE(
            session_duration=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).session_duration
    )
).ORDER_BY(total_duration.DESC())

tuc_past_month = Ewallet.CALCULATE(
    tuc=COUNT(UserSessions.WHERE(session_start_ts >= DATETIME('now', '-1 month')))
)

result = Merchants.CALCULATE(
    merchant_creation_year=YEAR(created_at),
    merchant_creation_month=MONTH(created_at)
).CALCULATE(
    mid=mid,
    name=name,
    num_coupons=COUNT(coupons.WHERE(
        (YEAR(created_at) == merchant_creation_year) & (MONTH(created_at) == merchant_creation_month)
    ))
).TOP_K(1, by=num_coupons.DESC())

merchant_ids_received_money = Transactions.WHERE(receiver_type == 1).PARTITION(name="merch_tx", by=(receiver_id)).CALCULATE(
    merchant_id=receiver_id
)

distinct_user_ids_with_transaction_notifications = Notifications.WHERE(
    notification_type == 'TRANSACTION'
).PARTITION(
    name="distinct_users", by=(user_id)
).CALCULATE(
    user_id=user_id
)

result = Ewallet.CALCULATE(
    median_merchant_balance=MEDIAN(
        Merchants.WHERE(
            (status == 'active') & CONTAINS(category, 'retail')
        ).balances.WHERE(
            updated_at >= DATETIME('now', 'start of day')
        ).balance
    )
)
